1	import { component$, useSignal, useVisibleTask$, $ } from "@builder.io/qwik";
2	import type { AiProviderType } from "../../types";
3	import { useConvexClient } from "../../utils/convex-context";
4	import { useAuth } from "../../utils/auth-context";
5	import { speak, speechState, stopSpeech } from "../../utils/speech";
6	
7	interface SpeakButtonProps {
8	  /** The prose to read. */
9	  text: string;
10	  /** Stable id for this passage, so only one button shows as active. */
11	  id: string;
12	  /** Fallback voice name, e.g. a persona's `speechVoice`. */
13	  voice?: string;
14	  /** Per-provider voice overrides, e.g. a persona's `speechVoices`. */
15	  voices?: Partial<Record<AiProviderType, string>>;
16	  /** Voice direction — a persona's `voice` lore paragraph fits here. */
17	  instructions?: string;
18	  /** Who is speaking, for the accessible label. */
19	  label?: string;
20	  /**
21	   * Who is speaking, by cast name. Callers holding a persona should pass
22	   * `voice`/`voices`/`instructions` directly; this is for the inline editor
23	   * cards, which know the author only as a string read off the mark.
24	   */
25	  author?: string;
26	  /** Slightly smaller styling for dense lists. */
27	  compact?: boolean;
28	}
29	
30	/**
31	 * A play/stop control for reading a passage aloud.
32	 *
33	 * Deliberately a single toggle rather than separate play and stop buttons:
34	 * only one thing can be sounding at a time, so the button that started it is
35	 * always the right place to look to stop it.
36	 *
37	 * Failure is shown as a tooltip and a colour change rather than a notice
38	 * block — a note that will not read aloud should not push the note itself off
39	 * the screen, and the writer can always just read it.
40	 */
41	export const SpeakButton = component$<SpeakButtonProps>((props) => {
42	  const clientSig = useConvexClient();
43	  const auth = useAuth();
44	  const status = useSignal<"idle" | "loading" | "playing" | "error">("idle");
45	  const errorMessage = useSignal("");
46	
47	  // eslint-disable-next-line qwik/no-use-visible-task
48	  useVisibleTask$(({ cleanup }) => {
49	    const sync = () => {
50	      const s = speechState();
51	      if (s.id === props.id) {
52	        status.value = s.status;
53	        errorMessage.value = s.error?.message ?? "";
54	      } else if (status.value !== "idle") {
55	        // Another passage took over; this button goes quiet.
56	        status.value = "idle";
57	        errorMessage.value = "";
58	      }
59	    };
60	    window.addEventListener("twyne:speech", sync);
61	    sync();
62	    cleanup(() => window.removeEventListener("twyne:speech", sync));
63	  });
64	
65	  const toggle = $(async () => {
66	    if (status.value === "playing" || status.value === "loading") {
67	      stopSpeech();
68	      return;
69	    }
70	    await speak({
71	      id: props.id,
72	      text: props.text,
73	      voice: props.voice,
74	      voices: props.voices,
75	      instructions: props.instructions,
76	      author: props.author ?? props.label,
77	      client: clientSig.value ?? null,
78	      signedIn: Boolean(auth.value.user),
79	    });
80	  });
81	
82	  const who = props.label ? ` in ${props.label}'s voice` : "";
83	  const title =
84	    status.value === "error"
85	      ? errorMessage.value || "Could not read this aloud"
86	      : status.value === "playing"
87	        ? "Stop reading"
88	        : `Read aloud${who}`;
89	
90	  return (
91	    <button
92	      onClick$={toggle}
93	      class={`focus-ring inline-flex items-center justify-center transition-colors ${
94	        props.compact ? "h-5 w-5" : "h-6 w-6"
95	      }`}
96	      style={{
97	        color:
98	          status.value === "error"
99	            ? "var(--color-accent-red)"
100	            : status.value === "playing"
101	              ? "var(--color-vermilion)"
102	              : "var(--color-ink-muted)",
103	        borderRadius: "2px",
104	      }}
105	      title={title}
106	      aria-label={title}
1...
